package dev.unbox.unpvp;

import java.util.*;
import net.minecraft.client.Minecraft;
import net.minecraft.client.resources.I18n;
import net.minecraft.client.renderer.*;
import net.minecraft.item.ItemStack;
import net.minecraft.potion.*;
import net.minecraft.scoreboard.*;
import net.minecraft.util.*;
import net.minecraftforge.client.event.RenderGameOverlayEvent;
import net.minecraftforge.fml.common.eventhandler.SubscribeEvent;
import org.lwjgl.opengl.GL11;

/** Native equipment/coordinate/effect HUD; scoreboard drawing adapted from VanillaHUD (GPL-3.0). */
final class ExtraHud {
 static final List<String> IDS=Arrays.asList("coordinates","armor","potions","scoreboard");
 static int potionIcons;
 private static final ResourceLocation POTION_TEXTURE=new ResourceLocation("textures/gui/container/inventory.png");
 private static Minecraft mc(){return Minecraft.getMinecraft();}
 static ScoreObjective objective(){if(mc().theWorld==null)return null;net.minecraft.scoreboard.Scoreboard board=mc().theWorld.getScoreboard();ScorePlayerTeam team=board.getPlayersTeam(mc().thePlayer.getName());ScoreObjective o=team==null||team.getChatFormat().getColorIndex()<0?null:board.getObjectiveInDisplaySlot(3+team.getChatFormat().getColorIndex());return o!=null?o:board.getObjectiveInDisplaySlot(1);}
 static List<Score> scores(ScoreObjective o){List<Score> out=new ArrayList<>();if(o!=null)for(Score s:o.getScoreboard().getSortedScores(o))if(s.getPlayerName()!=null&&!s.getPlayerName().startsWith("#"))out.add(s);return out.size()>15?new ArrayList<>(out.subList(out.size()-15,out.size())):out;}
 @SubscribeEvent public void render(RenderGameOverlayEvent.Post e){if(e.type!=RenderGameOverlayEvent.ElementType.ALL||mc().thePlayer==null||mc().gameSettings.hideGUI||mc().currentScreen instanceof UiScreen)return;boolean any=false;for(String id:IDS)any|=LiveHud.visible(id);if(!any)return;Painter.begin(1,0);try{for(String id:IDS)if(LiveHud.visible(id)){float[] b=Preview.bounds(id,e.resolution.getScaledWidth(),e.resolution.getScaledHeight());draw(id,b[0],b[1],false);}}finally{Painter.end();}}
 static List<String> lines(String id,boolean preview){List<String> out=new ArrayList<>();if(id.equals("coordinates")){
   double x=preview?9:mc().thePlayer.posX,y=preview?121:mc().thePlayer.posY,z=preview?3:mc().thePlayer.posZ;int decimals=UiState.number("coordinates.decimals",0,0,2);String format="%."+decimals+"f";String[] values={String.format(Locale.ROOT,format,x),String.format(Locale.ROOT,format,y),String.format(Locale.ROOT,format,z)};
   if(UiState.get("coordinates.layout","Stacked").equals("Stacked")){for(int i=0;i<3;i++)out.add((UiState.flag("coordinates.labels",true)?new String[]{"X  ","Y  ","Z  "}[i]:"")+values[i]);}else out.add(String.join(" / ",values));
   if(UiState.flag("coordinates.direction",true))out.add(preview?"NORTH":mc().thePlayer.getHorizontalFacing().getName().toUpperCase(Locale.ROOT));
   if(UiState.flag("coordinates.biome",false))out.add(preview?"Plains":mc().theWorld.getBiomeGenForCoords(mc().thePlayer.getPosition()).biomeName);
   if(UiState.flag("coordinates.dimension",false))out.add(preview?"Overworld":mc().theWorld.provider.getDimensionName());
   if(UiState.flag("coordinates.nether",false)){double factor=!preview&&mc().thePlayer.dimension==-1?8:1/8.;out.add(String.format(Locale.ROOT,"%s %.0f / %.0f",factor==8?"Overworld":"Nether",x*factor,z*factor));}
  }else if(id.equals("potions")){if(preview){out.add("Speed II  1:24");out.add("Strength  0:52");}else{for(PotionEffect effect:effects(false))out.add(I18n.format(effect.getEffectName())+(effect.getAmplifier()>0?" "+(effect.getAmplifier()+1):"")+"  "+Potion.getDurationString(effect));}}
  return out;
 }
 static int[] size(String id){int p=UiState.number(id+".padding",4,0,12),w=40,h=12;if(id.equals("armor")){List<ItemStack> items=equipment(mc().thePlayer==null||mc().currentScreen instanceof UiScreen);boolean horizontal=UiState.get("armor.layout","Vertical").equals("Horizontal");int cell=armorCell(items);return new int[]{p*2+(horizontal?items.size()*cell:cell),p*2+(horizontal?44:items.size()*(22+UiState.number("armor.spacing",4,0,12)))};}
  if(id.equals("scoreboard")){ScoreObjective o=mc().currentScreen instanceof UiScreen?null:objective();w=o==null?120:mc().fontRendererObj.getStringWidth(o.getDisplayName());for(Score score:scores(o)){String label=ScorePlayerTeam.formatPlayerName(o.getScoreboard().getPlayersTeam(score.getPlayerName()),score.getPlayerName())+(UiState.flag("scoreboard.showScores",true)?"  "+score.getScorePoints():"");w=Math.max(w,mc().fontRendererObj.getStringWidth(label));}h=(o==null?4:scores(o).size())*9+(UiState.flag("scoreboard.showTitle",true)?12:0);}
  else{List<String> lines=lines(id,mc().thePlayer==null||mc().currentScreen instanceof UiScreen);h=Math.max(12,lines.size()*12);for(String line:lines)w=Math.max(w,mc().fontRendererObj.getStringWidth(line));}if(id.equals("potions")){w+=22;h=effects(mc().thePlayer==null||mc().currentScreen instanceof UiScreen).size()*22;}return new int[]{w+p*2,h+p*2};
 }
 static List<PotionEffect> effects(boolean preview){if(preview)return Arrays.asList(new PotionEffect(Potion.moveSpeed.id,1680,1),new PotionEffect(Potion.damageBoost.id,1040,0));List<PotionEffect> out=new ArrayList<>(mc().thePlayer.getActivePotionEffects());Collections.sort(out,Comparator.comparingInt(PotionEffect::getPotionID));return out;}
 private static List<ItemStack> equipment(boolean sample){List<ItemStack> out=new ArrayList<>();String[] keys={"helmet","chestplate","leggings","boots","hand"};ItemStack[] samples=sample?new ItemStack[]{new ItemStack(net.minecraft.init.Items.diamond_helmet),new ItemStack(net.minecraft.init.Items.diamond_chestplate),new ItemStack(net.minecraft.init.Items.diamond_leggings),new ItemStack(net.minecraft.init.Items.diamond_boots),new ItemStack(net.minecraft.init.Items.diamond_sword)}:null;for(int i=0;i<5;i++)if(UiState.flag("armor."+keys[i],true)){ItemStack item=sample?samples[i]:i==4?mc().thePlayer.getHeldItem():mc().thePlayer.inventory.armorInventory[3-i];if(item!=null||UiState.flag("armor.empty",false))out.add(item);}if(UiState.flag("armor.reverse",false))Collections.reverse(out);return out;}
 private static String durability(ItemStack s){if(s==null||!s.isItemStackDamageable())return "";int max=s.getMaxDamage(),left=max-s.getItemDamage(),percent=max==0?0:left*100/max;String f=UiState.get("armor.format","Remaining");return f.equals("Off")?"":f.equals("Percentage")?percent+"%":f.equals("Both")?left+" ("+percent+"%)":f.equals("Remaining / Max")?left+" / "+max:""+left;}
 private static int armorCell(List<ItemStack> items){int w=65;for(ItemStack s:items)if(s!=null){w=Math.max(w,25+mc().fontRendererObj.getStringWidth(durability(s)));if(UiState.flag("armor.names",false))w=Math.max(w,25+mc().fontRendererObj.getStringWidth(s.getDisplayName()));}return w;}
 static void draw(String id,float x,float y,boolean preview){if(!preview&&id.equals("scoreboard")&&objective()==null)return;int[] size=size(id);int p=UiState.number(id+".padding",4,0,12),color=UiState.color(id+".color","#F4F6F8");GL11.glPushMatrix();GL11.glTranslatef(x,y,0);GL11.glScalef(Preview.factor(id),Preview.factor(id),1);
  try{if(UiState.flag(id+".background",false))Painter.round(0,0,size[0],size[1],UiState.flag(id+".rounded",true)?4:0,(UiState.number(id+".opacity",60,0,100)*255/100<<24)|(UiState.color(id+".backgroundColor","#191E24")&0xffffff));
   if(id.equals("armor")){List<ItemStack> items=equipment(preview);boolean horizontal=UiState.get("armor.layout","Vertical").equals("Horizontal");int cell=armorCell(items),i=0;for(ItemStack item:items){int xx=p+(horizontal?i*cell:0),yy=p+(horizontal?0:i*(22+UiState.number("armor.spacing",4,0,12)));i++;if(item==null)continue;
     GL11.glEnable(GL11.GL_TEXTURE_2D);GL11.glEnable(GL11.GL_DEPTH_TEST);GL11.glDepthMask(true);GlStateManager.bindTexture(0);GlStateManager.resetColor();GlStateManager.enableRescaleNormal();RenderHelper.enableGUIStandardItemLighting();mc().getRenderItem().renderItemAndEffectIntoGUI(item,xx,yy);if(UiState.flag("armor.count",true))mc().getRenderItem().renderItemOverlayIntoGUI(mc().fontRendererObj,item,xx,yy,null);RenderHelper.disableStandardItemLighting();GlStateManager.disableRescaleNormal();GL11.glDisable(GL11.GL_DEPTH_TEST);GL11.glDisable(GL11.GL_ALPHA_TEST);GL11.glEnable(GL11.GL_BLEND);GL11.glBlendFunc(GL11.GL_SRC_ALPHA,GL11.GL_ONE_MINUS_SRC_ALPHA);
     int tx=horizontal?xx:xx+21,ty=horizontal?yy+20:yy;float ratio=item.getMaxDamage()==0?1:(item.getMaxDamage()-item.getItemDamage())/(float)item.getMaxDamage();int c=ratio*100<UiState.number("armor.warning",20,0,100)?UiState.color("armor.warningColor","#EF7078"):color;
     if(UiState.flag("armor.names",false)){Preview.pixel(item.getDisplayName(),tx,ty,c);ty+=10;}Preview.pixel(durability(item),tx,ty,c,UiState.flag("armor.shadow",true));if(UiState.flag("armor.bar",true)&&item.isItemStackDamageable()){Painter.fill(tx,ty+10,35,2,0x66333333);Painter.fill(tx,ty+10,35*ratio,2,c);}
   }}else if(id.equals("scoreboard")){ScoreObjective o=preview?null:objective();String title=o==null?"Scoreboard":o.getDisplayName();int yy=p;if(UiState.flag("scoreboard.showTitle",true)){if(UiState.flag("scoreboard.background",false))Painter.fill(0,0,size[0],p+11,(UiState.number("scoreboard.titleOpacity",50,0,100)*255/100<<24)|(UiState.color("scoreboard.titleBackground","#000000")&0xffffff));Preview.pixel(title,(size[0]-mc().fontRendererObj.getStringWidth(title))/2f,yy,UiState.color("scoreboard.titleColor","#FFFFFF"),UiState.flag("scoreboard.shadow",true));yy+=12;}
     if(preview){Preview.pixel("Practice match",p,yy,color);Preview.pixel("Kills: 3",p,yy+9,color);Preview.pixel("Time: 01:24",p,yy+18,color);}else{List<Score> scores=scores(o);Collections.reverse(scores);for(Score score:scores){String name=ScorePlayerTeam.formatPlayerName(o.getScoreboard().getPlayersTeam(score.getPlayerName()),score.getPlayerName());Preview.pixel(name,p,yy,UiState.color("scoreboard.textColor","#FFFFFF"),UiState.flag("scoreboard.shadow",true));if(UiState.flag("scoreboard.showScores",true)){String value=""+score.getScorePoints();Preview.pixel(value,size[0]-p-mc().fontRendererObj.getStringWidth(value),yy,UiState.color("scoreboard.scoreColor","#FFFFFF"),UiState.flag("scoreboard.shadow",true));}yy+=9;}}
   }else if(id.equals("potions")){int yy=p;List<String> labels=lines(id,preview);int i=0;for(PotionEffect effect:effects(preview)){Potion potion=Potion.potionTypes[effect.getPotionID()];if(potion!=null&&potion.hasStatusIcon()){int icon=potion.getStatusIconIndex();GL11.glEnable(GL11.GL_TEXTURE_2D);GlStateManager.bindTexture(0);GlStateManager.resetColor();mc().getTextureManager().bindTexture(POTION_TEXTURE);net.minecraft.client.gui.Gui.drawModalRectWithCustomSizedTexture(p,yy,icon%8*18,198+icon/8*18,18,18,256,256);potionIcons++;}Preview.pixel(labels.get(i++),p+22,yy+5,color,UiState.flag("potions.shadow",true));yy+=22;}}else{int yy=p;for(String line:lines(id,preview)){Preview.pixel(line,p,yy,color,UiState.flag(id+".shadow",true));yy+=12;}}
  }finally{GL11.glPopMatrix();}
 }
}
